-- Social links shown in the footer and contact section

create table "public"."socials" (
  "id" bigint primary key generated by default as identity,
  "icon" varchar,
  "name" varchar,
  "url" varchar,
  "user" uuid,
  "order" smallint,
  "is_active" boolean default true,
  "copy_reference" varchar,
  constraint "socials_unique_together_user_order" unique ("user", "order")
);

alter table "public"."socials" add constraint "socials_user_fkey" foreign key ("user") references auth.users (id) on update cascade on delete cascade;

alter table "public"."socials" enable row level security;
create policy "Enable read access for all users" on "public"."socials" for select using (true);

grant all on "public"."socials" to postgres, anon, authenticated, service_role;
